/// Computes the triangular number of a given non-negative integer n.
pub fn triangle(n: u32) -> u32 {
    // The triangular number of n is n * (n + 1) / 2
    n * (n + 1) / 2
}

/// Proves that the triangular number function is monotonic:
/// if i ≤ j then triangle(i) ≤ triangle(j).
pub fn triangle_is_monotonic(i: u32, j: u32) -> bool {
    if i > j {
        return false;
    }
    triangle(i) <= triangle(j)
}

/// Tail-recursive procedure to compute the triangular number of a target n,
/// starting from a current index idx and accumulating the result in sum.
pub fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    if idx > n {
        return; // Base case: if idx exceeds n, we stop.
    }
    *sum += idx; // Accumulate the current index.
    tail_triangle(n, idx + 1, sum); // Recur with the next index.
}

fn main() {
    let n = 5;
    let mut sum = 0;
    tail_triangle(n, 1, &mut sum);
    println!("The triangular number of {} is {}", n, sum); // Output: The triangular number of 5 is 15
}